CREATE TABLE public.learning_reading_positions (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, parcours text NOT NULL, lesson_id text NOT NULL REFERENCES public.learning_lessons(id), section_index integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,parcours,lesson_id));
GRANT SELECT ON public.learning_reading_positions TO authenticated;
GRANT ALL ON public.learning_reading_positions TO service_role;
ALTER TABLE public.learning_reading_positions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own reading positions" ON public.learning_reading_positions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.save_learning_reading_position(p_lesson text,p_section integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; n integer; BEGIN SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); IF p IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour continuer.'; END IF; SELECT cardinality(body) INTO n FROM public.learning_lessons WHERE id=p_lesson AND published; IF n IS NULL OR n=0 OR p_section<0 OR p_section>=n THEN RAISE EXCEPTION 'Section indisponible.'; END IF; INSERT INTO public.learning_reading_positions(user_id,parcours,lesson_id,section_index) VALUES(auth.uid(),p,p_lesson,p_section) ON CONFLICT(user_id,parcours,lesson_id) DO UPDATE SET section_index=excluded.section_index,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.save_learning_reading_position(text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_learning_reading_position(text,integer) TO authenticated;
ALTER TABLE public.learning_sessions ADD COLUMN diagnostic_key uuid;
CREATE UNIQUE INDEX learning_diagnostic_once ON public.learning_sessions(user_id,diagnostic_key) WHERE diagnostic_key IS NOT NULL;
CREATE FUNCTION public.import_learning_diagnostic(p_key uuid,p_ids text[],p_answers jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; qs jsonb; sid uuid; score integer; BEGIN SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); IF p IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour sauvegarder votre test.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text||p_key::text)); SELECT id INTO sid FROM public.learning_sessions WHERE user_id=auth.uid() AND diagnostic_key=p_key; IF sid IS NOT NULL THEN RETURN sid; END IF; IF cardinality(p_ids)<>10 OR (SELECT count(DISTINCT x) FROM unnest(p_ids) x)<>10 OR jsonb_typeof(p_answers)<>'array' OR jsonb_array_length(p_answers)<>10 THEN RAISE EXCEPTION 'Test incomplet.'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_answers) a WHERE a::text !~ '^[0-3]$') THEN RAISE EXCEPTION 'Réponses invalides.'; END IF; SELECT jsonb_agg(to_jsonb(q) ORDER BY ids.n) INTO qs FROM unnest(p_ids) WITH ORDINALITY ids(id,n) JOIN public.learning_questions q ON q.id=ids.id AND q.published; IF qs IS NULL OR jsonb_array_length(qs)<>10 THEN RAISE EXCEPTION 'Ce test ne peut plus être associé : certaines questions ont été retirées.'; END IF; SELECT count(*) INTO score FROM jsonb_array_elements(qs) WITH ORDINALITY q(v,n) WHERE (p_answers->>((n-1)::integer))::integer=(v->>'answer')::integer; INSERT INTO public.learning_sessions(user_id,parcours,kind,questions,answers,total,correct,completed_at,current_index,diagnostic_key) VALUES(auth.uid(),p,'diagnostic',qs,(SELECT jsonb_object_agg((n-1)::text,v) FROM jsonb_array_elements(p_answers) WITH ORDINALITY a(v,n)),10,score,now(),9,p_key) RETURNING id INTO sid; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.import_learning_diagnostic(uuid,text[],jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.import_learning_diagnostic(uuid,text[],jsonb) TO authenticated;
CREATE FUNCTION public.review_learning_mistake(p_question text,p_answer integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; mastered boolean; BEGIN SELECT v INTO q FROM public.learning_sessions s CROSS JOIN LATERAL jsonb_array_elements(s.questions) WITH ORDINALITY a(v,n) WHERE s.user_id=auth.uid() AND s.completed_at IS NOT NULL AND v->>'id'=p_question AND (s.answers->>((n-1)::text))::integer IS DISTINCT FROM (v->>'answer')::integer ORDER BY s.started_at DESC LIMIT 1; IF q IS NULL THEN RAISE EXCEPTION 'Erreur introuvable.'; END IF; IF p_answer<0 OR p_answer>=jsonb_array_length(q->'options') THEN RAISE EXCEPTION 'Réponse invalide.'; END IF; mastered:=p_answer=(q->>'answer')::integer; INSERT INTO public.learning_mistake_reviews(user_id,question_id,mastered) VALUES(auth.uid(),p_question,mastered) ON CONFLICT(user_id,question_id) DO UPDATE SET mastered=excluded.mastered,updated_at=now(); RETURN mastered; END $$;
REVOKE ALL ON FUNCTION public.review_learning_mistake(text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.review_learning_mistake(text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.finish_learning_session(p_session uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.learning_sessions; score integer; BEGIN SELECT * INTO s FROM public.learning_sessions WHERE id=p_session AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Session indisponible.'; END IF; IF s.completed_at IS NOT NULL THEN RETURN; END IF; IF s.kind<>'exam' AND (SELECT count(*) FROM jsonb_object_keys(s.answers))<>s.total THEN RAISE EXCEPTION 'Terminez les questions avant de valider.'; END IF; SELECT count(*) INTO score FROM jsonb_array_elements(s.questions) WITH ORDINALITY q(value,n) WHERE (s.answers->>((n-1)::text))::integer=(value->>'answer')::integer; UPDATE public.learning_sessions SET correct=score,completed_at=CASE WHEN s.deadline IS NOT NULL THEN least(now(),s.deadline) ELSE now() END WHERE id=s.id; END $$;